define(["theme_boost/bootstrap/collapse"],function(Collapse){"use strict";function allOpen(t){return t.every(function(e){return e.classList.contains("show")})}function updateButton(t,e){if(!t)return;if(e.length&&allOpen(e)){t.textContent=t.dataset.labelClose;t.classList.remove("btn-outline-primary");t.classList.add("btn-primary")}else{t.textContent=t.dataset.labelOpen;t.classList.add("btn-outline-primary");t.classList.remove("btn-primary")}}return{init:function(){var container=document.querySelector(".qualiscope-dashboard");if(!container)return;var accordion=container.querySelector('[data-qualiscope="criteria-accordion"]');if(!accordion)return;var panes=Array.prototype.slice.call(accordion.querySelectorAll(".collapse"));if(!panes.length)return;var btn=container.querySelector('[data-qualiscope="criteria-toggleall"]');var openingAll=false;accordion.addEventListener("show.bs.collapse",function(e){if(openingAll)return;panes.forEach(function(pane){if(pane!==e.target&&pane.classList.contains("show")){Collapse.getOrCreateInstance(pane).hide()}})});accordion.addEventListener("shown.bs.collapse",function(){updateButton(btn,panes)});accordion.addEventListener("hidden.bs.collapse",function(){updateButton(btn,panes)});if(btn){btn.addEventListener("click",function(){var open=allOpen(panes);openingAll=!open;panes.forEach(function(pane){var instance=Collapse.getOrCreateInstance(pane);if(open){instance.hide()}else if(!pane.classList.contains("show")){instance.show()}});openingAll=false;updateButton(btn,panes)})}}}});